import type {readSplitHistory} from '@/lib/financial-split-history';
import {bankCloseMoney} from '@/lib/cashier-bank-close';
export function FinancialSplitHistory({history}:{history:ReturnType<typeof readSplitHistory>}){
 return <section aria-label="Split migration history"><h3>Split migration results</h3><p>Matched receivables: {bankCloseMoney(history.matched)}. Additional receivables: {bankCloseMoney(history.additional.receivable)}. Prepayments: {bankCloseMoney(history.additional.prepayment)}. Security deposits: {bankCloseMoney(history.additional.security)}.</p><div className="table-wrap"><table><caption>Posted portions of original balances</caption><thead><tr><th>Source item</th><th>Amount (USD)</th><th>Destination</th><th>Evidence</th></tr></thead><tbody>{history.openings.map(o=><tr key={o.opening}><td>{o.source}</td><td>{bankCloseMoney(o.amount)}</td><td>Opening: {o.opening}<br/>Journal: {o.journal}</td><td>{o.evidence}</td></tr>)}{history.matches.map(m=><tr key={m.id}><td>{m.source}</td><td>{bankCloseMoney(m.amount)}</td><td>Original invoice: {m.invoice}<br/>Current invoice: {m.currentInvoice}{m.corrections.length>0&&<ol aria-label="Invoice match correction history">{m.corrections.map(c=><li key={c.id}>Version {c.version}: {c.previous} to {c.invoice} — {c.reason} · {c.created} · Actor {c.actor}</li>)}</ol>}</td><td>{m.evidence}</td></tr>)}</tbody></table></div></section>;
}
